// auth-security · кейс auth-19 (#c3fdb1) — .qa/tests/auth-security/
// API-тесты под admin («באנגו דלי») на СУЩЕСТВУЮЩИХ тестовых заказах: #693 (утверждён, QA-AUTO-c3fdb1, 1 קבלה) и #694 (отклонён, QA-AUTO-c3fdb1-R).
// Ничего не создаётся: повторные approve/reject должны быть отклонены. Если заказы пересоздадут/изменят статус — обновить номера ниже.
// UI-сценарий двух вкладок («ההזמנה כבר אושרה.») требует нового заказа — отдельный тест @data, пропущен (см. ниже).
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { openApp, sb } from './_supabase';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const APPROVED_NO = 693;
const REJECTED_NO = 694;

type Snap = { order: any; notes: any[]; receipts: number };

async function order(page: import('@playwright/test').Page, no: number) {
  const r = await sb(page, 'GET', `orders?select=*&order_no=eq.${no}`);
  expect(r.status, `orders #${no}`).toBe(200);
  expect(r.body.length, `заказ #${no} найден`).toBe(1);
  return r.body[0];
}
async function snap(page: import('@playwright/test').Page, no: number): Promise<Snap> {
  const o = await order(page, no);
  const notes = await sb(page, 'GET', `order_notes?select=*&order_id=eq.${o.id}&order=id.asc`);
  expect(notes.status, 'order_notes читаются').toBe(200);
  const rec = await sb(page, 'GET', `order_receipts?select=id&order_id=eq.${o.id}`);
  expect(rec.status, 'order_receipts читаются').toBe(200);
  return { order: o, notes: notes.body, receipts: rec.body.length };
}

test.describe('auth-security — повторное approve/reject заказа блокируется (API)', () => {
  test('approve_order על הזמנה שאושרה → 400 / 22023 / ALREADY_APPROVED; אין הערה חדשה, updated_at ו-קבלה לא משתנים #c3fdb1 @desktop', async ({ page }) => {
    await openApp(page);
    const before = await snap(page, APPROVED_NO);
    test.skip(before.order.status !== 'approved', `#${APPROVED_NO} уже не «אושרה» (${before.order.status}) — обновить тестовые данные`);
    expect(before.receipts, 'до вызова одна קבלה').toBe(1);
    for (const args of [{ p_note: 'QA-AUTO-c3fdb1-api' }, {}]) {
      const r = await sb(page, 'POST', 'rpc/approve_order', { p_order_id: before.order.id, ...args });
      expect(r.status, `HTTP (${JSON.stringify(args)})`).toBe(400);
      expect(r.body?.code, 'код').toBe('22023');
      expect(String(r.body?.message)).toContain('ALREADY_APPROVED');
    }
    const after = await snap(page, APPROVED_NO);
    expect(after.notes, 'order_notes не изменились').toEqual(before.notes);
    expect(after.order.updated_at, 'updated_at не изменился').toBe(before.order.updated_at);
    expect(after.order, 'строка заказа не изменилась').toEqual(before.order);
    expect(after.receipts, 'קבלה по-прежнему одна').toBe(1);
  });

  test('approve_order על הזמנה שנדחתה → 400 / 22023 / ALREADY_REJECTED; סיבת הדחייה לא נמחקת #c3fdb1 @desktop', async ({ page }) => {
    await openApp(page);
    const before = await snap(page, REJECTED_NO);
    test.skip(before.order.status !== 'rejected', `#${REJECTED_NO} уже не «נדחתה» (${before.order.status}) — обновить тестовые данные`);
    const r = await sb(page, 'POST', 'rpc/approve_order', { p_order_id: before.order.id, p_note: 'QA-AUTO-c3fdb1-api' });
    expect(r.status, 'HTTP').toBe(400);
    expect(r.body?.code, 'код').toBe('22023');
    expect(String(r.body?.message)).toContain('ALREADY_REJECTED');
    const after = await snap(page, REJECTED_NO);
    expect(after.order.reject_reason, 'причина отказа не затёрта').toBe(before.order.reject_reason);
    expect(after.order, 'строка заказа не изменилась').toEqual(before.order);
    expect(after.notes, 'order_notes не изменились').toEqual(before.notes);
  });

  test('דחייה חוזרת (PATCH orders status=rejected) של הזמנה שנדחתה → 400 / ALREADY_REJECTED; סיבת הדחייה לא נדרסת #c3fdb1 @desktop', async ({ page }) => {
    await openApp(page);
    const before = await snap(page, REJECTED_NO);
    test.skip(before.order.status !== 'rejected', `#${REJECTED_NO} уже не «נדחתה» (${before.order.status})`);
    // В UI отклонение — прямой PATCH /rest/v1/orders?id=eq.<id> {status, reject_reason} (не RPC).
    const r = await sb(page, 'PATCH', `orders?id=eq.${before.order.id}`, { status: 'rejected', reject_reason: 'QA-AUTO-c3fdb1-overwrite' }, 'return=minimal');
    expect(r.status, 'HTTP').toBe(400);
    expect(String(r.body?.message)).toContain('ALREADY_REJECTED');
    const after = await snap(page, REJECTED_NO);
    expect(after.order.reject_reason, 'причина отказа не перезаписана').toBe(before.order.reject_reason);
    expect(after.order).toEqual(before.order);
  });

  test('דחייה של הזמנה שאושרה (PATCH status=rejected על #693) → 400 / INVALID_STATUS_TRANSITION:approved->rejected, ההזמנה לא משתנה #c3fdb1 @desktop', async ({ page }) => {
    await openApp(page);
    const before = await snap(page, APPROVED_NO);
    test.skip(before.order.status !== 'approved', `#${APPROVED_NO} уже не «אושרה» (${before.order.status})`);
    const r = await sb(page, 'PATCH', `orders?id=eq.${before.order.id}`, { status: 'rejected', reject_reason: 'QA-AUTO-c3fdb1-api' }, 'return=minimal');
    expect(r.status, 'HTTP').toBe(400);
    expect(String(r.body?.message)).toContain('INVALID_STATUS_TRANSITION');
    const after = await snap(page, APPROVED_NO);
    expect(after.order, 'строка заказа не изменилась').toEqual(before.order);
    expect(after.notes).toEqual(before.notes);
  });

  test('UI: אישור בלשונית מיושנת של הזמנה שכבר אושרה → «ההזמנה כבר אושרה.» + רענון הכרטיס #c3fdb1 @desktop @data', async () => {
    test.skip(true, 'нужен новый заказ в «ממתינה לאישור» (buyer создаёт, admin утверждает в одной вкладке, жмёт «אשר» во второй) — создаёт неудаляемый заказ; писать только по решению пользователя');
  });
});
